import{_ as t,c as i,o as s,j as n,Y as r,t as o}from"./chunks/framework.BNTND4LZ.js";const f=JSON.parse('{"title":"units | x-cmd man (man7) | decimal and binary prefixes","titleTemplate":false,"description":"x-cmd man (man7 Manual Page) | units - decimal and binary prefixes","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"units | x-cmd man (man7) | decimal and binary prefixes"}],["meta",{"name":"og:description","content":"x-cmd man (man7 Manual Page) | units - decimal and binary prefixes"}]]},"headers":[],"params":{"isMan":true,"man":"units","category":"man7","desc":"decimal and binary prefixes"},"relativePath":"man7/units.md","filePath":"man7/[man].md"}'),l={name:"man7/units.md"},d={class:"visually-hidden"};function h(a,e,p,m,c,u){return s(),i("div",null,[n("h1",d,o(a.$params.man),1),e[0]||(e[0]=r('<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>units - decimal and binary prefixes</p><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><h3 id="decimal-prefixes" tabindex="-1">Decimal prefixes <a class="header-anchor" href="#decimal-prefixes" aria-label="Permalink to &quot;Decimal prefixes&quot;">​</a></h3><p>The SI system of units uses prefixes that indicate powers of ten. A kilometer is 1000 meter, and a megawatt is 1000000 watt. Below the standard prefixes.</p><blockquote><hr><p>Prefix Name Value q quecto 10^-30 = 0.000000000000000000000000000001 r ronto 10^-27 = 0.000000000000000000000000001 y yocto 10^-24 = 0.000000000000000000000001 z zepto 10^-21 = 0.000000000000000000001 a atto 10^-18 = 0.000000000000000001 f femto 10^-15 = 0.000000000000001 p pico 10^-12 = 0.000000000001 n nano 10^-9 = 0.000000001 µ micro 10^-6 = 0.000001 m milli 10^-3 = 0.001 c centi 10^-2 = 0.01 d deci 10^-1 = 0.1 da deka 10^ 1 = 10 h hecto 10^ 2 = 100 k kilo 10^ 3 = 1000 M mega 10^ 6 = 1000000 G giga 10^ 9 = 1000000000 T tera 10^12 = 1000000000000 P peta 10^15 = 1000000000000000 E exa 10^18 = 1000000000000000000 Z zetta 10^21 = 1000000000000000000000 Y yotta 10^24 = 1000000000000000000000000 R ronna 10^27 = 1000000000000000000000000000 Q quetta 10^30 = 1000000000000000000000000000000</p><hr></blockquote><p>The symbol for micro is the Greek letter mu, often written u in an ASCII context where this Greek letter is not available.</p><h3 id="binary-prefixes" tabindex="-1">Binary prefixes <a class="header-anchor" href="#binary-prefixes" aria-label="Permalink to &quot;Binary prefixes&quot;">​</a></h3><p>The binary prefixes resemble the decimal ones, but have an additional &#39;i&#39; (and &quot;Ki&quot; starts with a capital &#39;K&#39;). The names are formed by taking the first syllable of the names of the decimal prefix with roughly the same size, followed by &quot;bi&quot; for &quot;binary&quot;.</p><blockquote><hr><p>Prefix Name Value Ki kibi 2^10 = 1024 Mi mebi 2^20 = 1048576 Gi gibi 2^30 = 1073741824 Ti tebi 2^40 = 1099511627776 Pi pebi 2^50 = 1125899906842624 Ei exbi 2^60 = 1152921504606846976 Zi zebi 2^70 = 1180591620717411303424 Yi yobi 2^80 = 1208925819614629174706176</p><hr></blockquote><h3 id="discussion" tabindex="-1">Discussion <a class="header-anchor" href="#discussion" aria-label="Permalink to &quot;Discussion&quot;">​</a></h3><p>Before these binary prefixes were introduced, it was fairly common to use k=1000 and K=1024, just like b=bit, B=byte. Unfortunately, the M is capital already, and cannot be capitalized to indicate binary-ness.</p><p>At first that didn&#39;t matter too much, since memory modules and disks came in sizes that were powers of two, so everyone knew that in such contexts &quot;kilobyte&quot; and &quot;megabyte&quot; meant 1024 and 1048576 bytes, respectively. What originally was a sloppy use of the prefixes &quot;kilo&quot; and &quot;mega&quot; started to become regarded as the &quot;real true meaning&quot; when computers were involved. But then disk technology changed, and disk sizes became arbitrary numbers. After a period of uncertainty all disk manufacturers settled on the standard, namely k=1000, M=1000 k, G=1000 M.</p><p>The situation was messy: in the 14k4 modems, k=1000; in the 1.44 MB diskettes, M=1024000; and so on. In 1998 the IEC approved the standard that defines the binary prefixes given above, enabling people to be precise and unambiguous.</p><p>Thus, today, MB = 1000000 B and MiB = 1048576 B.</p><p>In the free software world programs are slowly being changed to conform. When the Linux kernel boots and says</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">hda:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 120064896</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sectors</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (61473 </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">MB</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) w/2048KiB Cache</span></span></code></pre></div><p>the MB are megabytes and the KiB are kibibytes.</p><h2 id="see-also" tabindex="-1">SEE ALSO <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;SEE ALSO&quot;">​</a></h2><p><a href="https://www.bipm.org/documents/20126/41483022/SI-Brochure-9.pdf" target="_blank" rel="noreferrer">The International System of Units</a>.</p>',20))])}const y=t(l,[["render",h]]);export{f as __pageData,y as default};
